		// Stats at the bottom of the shop
		statsLabel.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
		statsLabel.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		statsLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
