	/**
	 * The clickable rune: a custom-painted sprite with a smoothly animated
	 * scale. Hover eases up to 110%, pressing dips to 90% (brightened),
	 * releasing springs back — always expanding/shrinking around the center.
	 */
	private class RuneButton extends javax.swing.JComponent
	{
		private java.awt.image.BufferedImage sprite;
		private java.awt.image.BufferedImage brightSprite;
		private String label = "";
		private boolean clickable;
		private boolean hovered;
		private boolean pressed;
		private double scale = 1.0;
		private double targetScale = 1.0;
		private final Timer anim = new Timer(16, e -> stepAnim());

		RuneButton()
		{
			setPreferredSize(new Dimension(120, 116));
			setMaximumSize(new Dimension(120, 116));
			setCursor(new java.awt.Cursor(java.awt.Cursor.HAND_CURSOR));
			addMouseListener(new java.awt.event.MouseAdapter()
			{
				@Override
				public void mouseEntered(java.awt.event.MouseEvent e)
				{
					hovered = true;
					setTarget(1.1);
				}

				@Override
				public void mouseExited(java.awt.event.MouseEvent e)
				{
					hovered = false;
					pressed = false;
					setTarget(1.0);
				}

				@Override
				public void mousePressed(java.awt.event.MouseEvent e)
				{
					if (!clickable)
					{
						return;
					}
					pressed = true;
					setTarget(0.9);
				}

				@Override
				public void mouseReleased(java.awt.event.MouseEvent e)
				{
					boolean wasPressed = pressed;
					pressed = false;
					setTarget(hovered ? 1.1 : 1.0);
					if (wasPressed && clickable && contains(e.getPoint()))
					{
						onRuneClicked();
					}
				}
			});
		}

		void setSprite(java.awt.image.BufferedImage src)
		{
			// Copy into a plain ARGB buffer (drawn scaled at paint time) and
			// derive the brightened pressed-state version once
			java.awt.image.BufferedImage buf = new java.awt.image.BufferedImage(
				src.getWidth(), src.getHeight(), java.awt.image.BufferedImage.TYPE_INT_ARGB);
			java.awt.Graphics2D g = buf.createGraphics();
			g.drawImage(src, 0, 0, null);
			g.dispose();
			sprite = buf;
			brightSprite = new java.awt.image.RescaleOp(
				new float[]{1.25f, 1.25f, 1.25f, 1f}, new float[4], null).filter(buf, null);
			repaint();
		}

		void setState(String newLabel, boolean nowClickable)
		{
			label = newLabel;
			clickable = nowClickable;
			repaint();
		}

		private void setTarget(double target)
		{
			targetScale = target;
			if (!anim.isRunning())
			{
				anim.start();
			}
		}

		private void stepAnim()
		{
			scale += (targetScale - scale) * 0.3; // ease toward target
			if (Math.abs(scale - targetScale) < 0.004)
			{
				scale = targetScale;
				anim.stop();
			}
			repaint();
		}

		@Override
		protected void paintComponent(java.awt.Graphics g)
		{
			super.paintComponent(g);
			java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
			g2.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION,
				java.awt.RenderingHints.VALUE_INTERPOLATION_BILINEAR);

			int spriteArea = getHeight() - 20; // bottom strip reserved for the label
			java.awt.image.BufferedImage img = pressed && brightSprite != null ? brightSprite : sprite;
			if (img != null && clickable)
			{
				int size = (int) (RUNE_SIZE * scale);
				g2.drawImage(img, (getWidth() - size) / 2, (spriteArea - size) / 2, size, size, null);
			}

			g2.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
			g2.setColor(getForeground());
			java.awt.FontMetrics fm = g2.getFontMetrics();
			g2.drawString(label, (getWidth() - fm.stringWidth(label)) / 2, getHeight() - 5);
			g2.dispose();
		}
	}

	/**
	 * Hosts the rune button and paints crit fire over it: flame-colored embers
	 * (plus the occasional tiny fire-rune sprite) rise from the rune, drift,
	 * and fade out over ~a second.
	 */
	private class ConfettiPane extends JPanel
	{
		// x, y, xVelocity, yVelocity, colorIndex, life (1.0 -> 0), isIcon (0/1)
		private final java.util.List<double[]> particles = new java.util.ArrayList<>();
		private final java.awt.Color[] colors = {
			new java.awt.Color(255, 69, 0), new java.awt.Color(255, 140, 0),
			new java.awt.Color(255, 200, 60), new java.awt.Color(255, 90, 40),
			new java.awt.Color(220, 50, 30),
		};
		private final Timer animator = new Timer(30, e -> step());
		private java.awt.Image fireIcon;
		private boolean fireIconRequested;

		ConfettiPane()
		{
			super(new java.awt.GridBagLayout());
			setOpaque(false);
			Dimension size = new Dimension(180, 140);
			setPreferredSize(size);
			setMaximumSize(size);
			// NOTE: no itemManager use here — this constructor runs as a field
			// initializer, before the outer panel's constructor assigns it
		}

		void burst()
		{
			// Lazy-load the fire-rune sprite on first use (itemManager is set by now)
			if (!fireIconRequested)
			{
				fireIconRequested = true;
				AsyncBufferedImage img = itemManager.getImage(ItemID.FIRE_RUNE);
				Runnable apply = () ->
					fireIcon = img.getScaledInstance(14, 14, java.awt.Image.SCALE_SMOOTH);
				apply.run();
				img.onLoaded(apply);
			}
			double cx = getWidth() / 2.0;
			double cy = getHeight() / 2.0;
			for (int i = 0; i < 24; i++)
			{
				boolean icon = random.nextInt(5) == 0; // ~20% are fire-rune sprites
				particles.add(new double[]{
					cx + (random.nextDouble() - 0.5) * 60, // spread across the rune
					cy + 10 + random.nextDouble() * 15,    // start near its base
					(random.nextDouble() - 0.5) * 1.6,     // slight sideways drift
					-(1.5 + random.nextDouble() * 2.5),    // rising
					random.nextInt(colors.length),
					0.8 + random.nextDouble() * 0.4,
					icon ? 1 : 0,
				});
			}
			if (!animator.isRunning())
			{
				animator.start();
			}
		}

		private void step()
		{
			for (java.util.Iterator<double[]> it = particles.iterator(); it.hasNext(); )
			{
				double[] p = it.next();
				p[0] += p[2] + Math.sin(p[1] * 0.15) * 0.6; // flicker/wobble as it rises
				p[1] += p[3];
				p[3] -= 0.05; // buoyancy: embers accelerate upward slightly
				p[5] -= 0.04;
				if (p[5] <= 0)
				{
					it.remove();
				}
			}
			if (particles.isEmpty())
			{
				animator.stop();
			}
			repaint();
		}

		@Override
		public void paint(java.awt.Graphics g)
		{
			super.paint(g); // children (the rune button) first, fire on top
			java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
			for (double[] p : particles)
			{
				g2.setComposite(java.awt.AlphaComposite.getInstance(
					java.awt.AlphaComposite.SRC_OVER, (float) Math.max(0, Math.min(1, p[5]))));
				if (p[6] == 1 && fireIcon != null)
				{
					g2.drawImage(fireIcon, (int) p[0], (int) p[1], null);
				}
				else
				{
					g2.setColor(colors[(int) p[4]]);
					int size = 2 + (int) (p[5] * 4);
					g2.fillOval((int) p[0], (int) p[1], size, size);
				}
			}
			g2.dispose();
		}
	}

	/**
	 * HTML labels don't wrap to the space they're given — they demand the width
	 * of their longest line, which pushed the Buy buttons out of the narrow
	 * sidebar. A fixed body width forces wrapping instead.
	 */
	private static String html(String inner)
	{
		// Narrower than before: shop rows now also fit a 22px item icon
		return "<html><body style='width:76px'>" + inner + "</body></html>";
	}

	/** For per-second/per-click rates, which can be fractional (e.g. 0.5/s). */
	private static String formatRate(double value)
	{
		if (value >= 1_000)
		{
			return format(value);
		}
		return value == Math.floor(value)
			? String.valueOf((long) value)
			: String.format("%.1f", value);
	}

	private static String format(double value)
	{
		// Full digits with thousand separators ("1,000,000"), no suffixes.
		// Fallback to scientific notation only where long overflows (~9.2e18).
		if (value < Long.MAX_VALUE)
		{
			return String.format("%,d", (long) value);
		}
		return String.format("%.2e", value);
	}
}

package com.skedpojkar.panel;

import com.skedpojkar.multiplayer.PartyTicTacToe;
import java.awt.BorderLayout;
import java.awt.Font;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;

/**
 * Party tic-tac-toe. Requires both players to run this plugin and be in the
 * same RuneLite party. The member with the lowest party id is X and moves
 * first; turns alternate and wins/draws are detected.
 */
public class MultiplayerPanel extends JPanel
{
	private final PartyTicTacToe game;
	private final JLabel partyStatus = new JLabel();
	private final JLabel gameStatus = new JLabel();
	private final JButton[] cells = new JButton[9];

	public MultiplayerPanel(PartyTicTacToe game)
	{
		this.game = game;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		gameStatus.setFont(gameStatus.getFont().deriveFont(Font.BOLD));

		JPanel statusBox = new JPanel();
		statusBox.setLayout(new BoxLayout(statusBox, BoxLayout.Y_AXIS));
		statusBox.setOpaque(false);
		statusBox.add(partyStatus);
		statusBox.add(gameStatus);

		JPanel grid = new JPanel(new GridLayout(3, 3, 4, 4));
		grid.setOpaque(false);
		for (int i = 0; i < 9; i++)
		{
			final int cell = i;
			cells[i] = TttUi.createCell();
			cells[i].addActionListener(e -> onCellClicked(cell));
			grid.add(cells[i]);
		}

		JButton resetButton = new JButton("Reset board");
		resetButton.addActionListener(e -> game.sendReset());

		JButton refreshButton = new JButton("Refresh party status");
		refreshButton.addActionListener(e -> refresh());

		JPanel buttons = new JPanel(new GridLayout(2, 1, 0, 4));
		buttons.setOpaque(false);
		buttons.add(resetButton);
		buttons.add(refreshButton);

		add(statusBox, BorderLayout.NORTH);
		add(TttUi.center(grid), BorderLayout.CENTER);
		add(buttons, BorderLayout.SOUTH);

		game.setBoardListener(this::refresh);
		refresh();
	}

	private void onCellClicked(int cell)
	{
		// Ignored by the game when it's not our turn or we're not in a party.
		// The board updates when the move echoes back from the party server,
		// so a short delay before the symbol appears is expected.
		game.sendMove(cell);
		refresh();
	}

	private void refresh()
	{
		partyStatus.setText("<html>" + game.getPartyStatus() + "</html>");
		gameStatus.setText(game.getGameStatus());

		String[] board = game.getBoard();
		for (int i = 0; i < cells.length; i++)
		{
			TttUi.setCell(cells[i], board[i]);
		}
	}
}

package com.skedpojkar.panel;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridBagLayout;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * Shared look for the tic-tac-toe boards: square cells that stand out from the
 * side panel, and colored symbols (X cyan, O orange).
 */
final class TttUi
{
	static final Color X_COLOR = new Color(0, 200, 255);
	static final Color O_COLOR = ColorScheme.BRAND_ORANGE;

	private TttUi()
	{
	}

	static JButton createCell()
	{
		JButton cell = new JButton("");
		cell.setPreferredSize(new Dimension(58, 58));
		cell.setFont(cell.getFont().deriveFont(Font.BOLD, 26f));
		cell.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		cell.setFocusPainted(false);
		cell.setBorder(BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR, 1));
		return cell;
	}

	/** Sets a cell's symbol ("X", "O" or null to clear) with its color. */
	static void setCell(JButton cell, String symbol)
	{
		cell.setText(symbol == null ? "" : symbol);
		cell.setForeground("O".equals(symbol) ? O_COLOR : X_COLOR);
	}

	/** Wraps the 3x3 grid so it keeps its square size instead of stretching to fill the panel. */
	static JPanel center(JPanel grid)
	{
		JPanel wrapper = new JPanel(new GridBagLayout());
		wrapper.setOpaque(false);
		wrapper.add(grid);
		return wrapper;
	}
}

package com.skedpojkar.announce;

import com.skedpojkar.SkedpojkarConfig;
import com.skedpojkar.achievements.Achievement;
import com.skedpojkar.achievements.AchievementManager;
import com.skedpojkar.sound.Sound;
import com.skedpojkar.sound.SoundEngine;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Feature 1: reacts to in-game events with local chat messages and sounds.
 *
 * Triggers are keyed by event/message type only, never by player name —
 * player-targeted triggers are rejected by RuneLite (generic player
 * highlighting, see the Rejected-or-Rolled-Back-Features wiki page).
 */
@Slf4j
@Singleton
public class AnnouncementTriggers
{
	// PvP kill attribution: the API has no "you killed X" event, so we count a kill
	// as ours if we landed a hitsplat on the player within this window before death.
	private static final long KILL_ATTRIBUTION_WINDOW_MS = 5_000L;
	private static final long PVP_KILL_SOUND_DELAY_MS = 2_000L;
	private static final int PVP_ZERO_HIT_CHANCE_PERCENT = 30;

	// The Al Kharid toll gate sits on the x=3268 fence line, gate tiles at y 3227-3228.
	// TODO verify in-game; adjust if the sound fires at the wrong spot or not at all.
	private static final int GATE_X = 3268;
	private static final int GATE_MIN_Y = 3226;
	private static final int GATE_MAX_Y = 3229;

	// Wordings confirmed in-game 2026-07-11
	private static final String SEPULCHRE_FLOOR_5_MESSAGE = "You have completed Floor 5 of the Hallowed Sepulchre";
	private static final String GAUNTLET_MESSAGE = "Corrupted challenge duration";

	// Clan broadcast phrases. TODO verify against real broadcasts in-game; clans
	// only broadcast the event types enabled in their clan settings.
	private static final String CLAN_DEATH_PHRASE = "has been defeated by";
	private static final String CLAN_DEATH_PHRASE_2 = "has died";
	private static final String CLAN_KILL_PHRASE = "has defeated";
	private static final String CLAN_DROP_PHRASE = "received a drop";

	// The secret PM sequence: these phrases must arrive in this order as private
	// messages (each its own PM, exact match, case-insensitive) to trigger the
	// reaction. Hardcoded on purpose.
	private static final String[] PM_SEQUENCE_PHRASES = {
		"yag",
		"si",
		"pilif",
	};

	// Player-owned-house amenity check. Object names verified in-game 2026-07-18:
	// the exit is named just "Portal", and a POH is full of "... space" build
	// hotspots — requiring both is a solid house fingerprint that other
	// instanced content won't match.
	private static final String POH_PORTAL_NAME = "Portal";
	private static final String POH_HOTSPOT_SUFFIX = " space";
	private static final String POH_ORNATE_POOL_PREFIX = "Ornate pool";
	private static final String POH_ORNATE_JEWELLERY_BOX_NAME = "Ornate jewellery box";
	// Ticks to wait after a region load before judging the house contents
	private static final int POH_SETTLE_TICKS = 3;

	@Inject
	private Client client;

	@Inject
	private SkedpojkarConfig config;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private ItemManager itemManager;

	@Inject
	private AchievementManager achievements;

	private final Map<Skill, Integer> previousLevels = new EnumMap<>(Skill.class);
	private final Map<String, Long> lastPvpHit = new HashMap<>();
	private final Random random = new Random();

	private WorldPoint lastTickPosition;
	private int pmSequenceProgress;
	private boolean bankWarnedThisSession;

	// POH scan state, reset on every region load
	private boolean houseCheckPending;
	private int houseSettleTicks;
	private boolean sawExitPortal;
	private boolean sawBuildHotspot;
	private boolean sawOrnatePool;
	private boolean sawOrnateJewelleryBox;
	private final java.util.Set<String> scannedObjectNames = new java.util.HashSet<>();

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGING_IN)
		{
			previousLevels.clear();
			lastPvpHit.clear();
			lastTickPosition = null;
			pmSequenceProgress = 0;
			bankWarnedThisSession = false;
		}
		else if (event.getGameState() == GameState.LOADING)
		{
			// Every region load could be a house teleport; collect objects and judge later
			houseCheckPending = true;
			houseSettleTicks = 0;
			sawExitPortal = false;
			sawBuildHotspot = false;
			sawOrnatePool = false;
			sawOrnateJewelleryBox = false;
			scannedObjectNames.clear();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// The first StatChanged per skill after login is the baseline, not a level-up
		Integer previous = previousLevels.put(event.getSkill(), event.getLevel());
		if (previous == null || event.getLevel() <= previous || !config.announceLevelUps())
		{
			return;
		}

		announce("Level up: " + event.getSkill().getName() + " is now " + event.getLevel() + ". Gamer.");
		soundEngine.play(Sound.LEVEL_UP);
	}

	/**
	 * Tracks our hits on other players (for kill attribution) and plays the
	 * PvP zero-hit sound on a 30% roll.
	 */
	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!(event.getActor() instanceof Player) || event.getActor() == client.getLocalPlayer())
		{
			return;
		}
		Hitsplat hitsplat = event.getHitsplat();
		if (!hitsplat.isMine())
		{
			return;
		}

		Player player = (Player) event.getActor();
		if (player.getName() != null)
		{
			lastPvpHit.put(Text.standardize(player.getName()), System.currentTimeMillis());
		}

		if (hitsplat.getAmount() == 0)
		{
			achievements.count(Achievement.WHIFF_MASTER, 25);
			if (config.pvpZeroHitSound() && random.nextInt(100) < PVP_ZERO_HIT_CHANCE_PERCENT)
			{
				soundEngine.play(Sound.PVP_ZERO_HIT);
			}
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!(event.getActor() instanceof Player))
		{
			return;
		}
		Player player = (Player) event.getActor();

		if (player == client.getLocalPlayer())
		{
			if (config.announceOwnDeath())
			{
				announce("You died.");
				soundEngine.play(Sound.OWN_DEATH);
			}
			return;
		}

		// PvP kill: we damaged this player recently, so count the kill as ours
		String key = player.getName() == null ? null : Text.standardize(player.getName());
		Long lastHit = key == null ? null : lastPvpHit.remove(key);
		if (lastHit != null && System.currentTimeMillis() - lastHit < KILL_ATTRIBUTION_WINDOW_MS)
		{
			achievements.count(Achievement.PVP_MENACE, 10);
			if (config.pvpKillSound())
			{
				soundEngine.play(Sound.PVP_KILL, PVP_KILL_SOUND_DELAY_MS);
			}
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		String message = Text.removeTags(event.getMessage());

		switch (event.getType())
		{
			// SPAM is the "Game: Filtered" message type — completion/duration
			// messages (Sepulchre, Gauntlet) often arrive as SPAM, not GAMEMESSAGE
			case GAMEMESSAGE:
			case SPAM:
				if (message.startsWith(SEPULCHRE_FLOOR_5_MESSAGE))
				{
					achievements.unlock(Achievement.FLOOR_5_ENJOYER);
					if (config.sepulchreSound())
					{
						soundEngine.play(Sound.SEPULCHRE_FLOOR_5);
					}
				}
				else if (message.startsWith(GAUNTLET_MESSAGE))
				{
					achievements.unlock(Achievement.CORRUPTED);
					if (config.goodJobSound())
					{
						soundEngine.play(Sound.GOOD_JOB);
					}
				}
				break;

			// System broadcasts in the clan channel (kills, deaths, drops, ...).
			// Matched by broadcast type only — never by who is mentioned.
			case CLAN_MESSAGE:
				handleClanBroadcast(message);
				break;

			// Any member talking in the clan or friends channel
			case CLAN_CHAT:
			case FRIENDSCHAT:
				if (config.clanChatSound())
				{
					soundEngine.play(Sound.CLAN_CHAT);
				}
				break;

			// Incoming private messages: secret-sequence detection.
			// Matches message content only, regardless of who sent it.
			case PRIVATECHAT:
				handlePrivateMessage(message);
				break;

			default:
				break;
		}
	}

	/**
	 * Advances through the hardcoded secret phrase sequence: each incoming PM
	 * must exactly match the next phrase (case-insensitive). A wrong message
	 * resets progress (or counts as a fresh start if it matches the first
	 * phrase). Completing the sequence triggers the reaction.
	 */
	private void handlePrivateMessage(String message)
	{
		String msg = message.trim();
		if (msg.equalsIgnoreCase(PM_SEQUENCE_PHRASES[pmSequenceProgress]))
		{
			pmSequenceProgress++;
		}
		else
		{
			pmSequenceProgress = msg.equalsIgnoreCase(PM_SEQUENCE_PHRASES[0]) ? 1 : 0;
		}

		if (pmSequenceProgress >= PM_SEQUENCE_PHRASES.length)
		{
			pmSequenceProgress = 0;
			achievements.unlock(Achievement.THE_SEQUENCE);
			announce("The secret sequence has been spoken.");
			soundEngine.play(Sound.PM_SEQUENCE);
		}
	}

	private void handleClanBroadcast(String message)
	{
		// Deaths first: "X has been defeated by Y" must not match the kill phrase
		if (config.clanDeathSound()
			&& (message.contains(CLAN_DEATH_PHRASE) || message.contains(CLAN_DEATH_PHRASE_2)))
		{
			soundEngine.play(Sound.CLAN_DEATH);
		}
		else if (config.clanKillSound() && message.contains(CLAN_KILL_PHRASE))
		{
			soundEngine.play(Sound.CLAN_KILL);
		}
		else if (config.clanDropSound() && message.contains(CLAN_DROP_PHRASE))
		{
			soundEngine.play(Sound.CLAN_DROP);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		checkGateCrossing(local);
		checkHouseAmenities();
	}

	/**
	 * Detects passing the Al Kharid toll gate by watching for the player's position
	 * crossing the gate's fence line between ticks (running covers 2 tiles per tick,
	 * so checking "standing on the gate tile" would miss crossings).
	 */
	private void checkGateCrossing(Player local)
	{
		WorldPoint current = local.getWorldLocation();
		WorldPoint previous = lastTickPosition;
		lastTickPosition = current;

		if (previous == null || current.getPlane() != 0 || previous.getPlane() != 0)
		{
			return;
		}

		boolean nearGate = current.getY() >= GATE_MIN_Y && current.getY() <= GATE_MAX_Y
			&& previous.getY() >= GATE_MIN_Y && previous.getY() <= GATE_MAX_Y;
		boolean crossed = (previous.getX() < GATE_X && current.getX() >= GATE_X)
			|| (previous.getX() >= GATE_X && current.getX() < GATE_X);
		if (!nearGate || !crossed)
		{
			return;
		}

		achievements.count(Achievement.TOLL_DODGER, 10);
		if (config.goodJobSound())
		{
			soundEngine.play(Sound.GOOD_JOB);
		}
		if (config.princeAliGateMessage()
			&& Quest.PRINCE_ALI_RESCUE.getState(client) == QuestState.FINISHED)
		{
			announce("Hey, you've done Prince Ali Rescue, wow!");
		}
	}

	/**
	 * A few ticks after a region load, judge whether we're in a player-owned house
	 * (spotted its exit portal) that lacks the best pool and/or jewellery box.
	 */
	private void checkHouseAmenities()
	{
		if (!houseCheckPending || ++houseSettleTicks < POH_SETTLE_TICKS)
		{
			return;
		}
		houseCheckPending = false;

		if (!scannedObjectNames.isEmpty())
		{
			log.debug("Instance scan: portal={} hotspots={} pool={} box={} objects={}",
				sawExitPortal, sawBuildHotspot, sawOrnatePool, sawOrnateJewelleryBox, scannedObjectNames);
		}

		if (!config.houseAmenitiesCheck() || !sawExitPortal || !sawBuildHotspot)
		{
			return;
		}
		if (!sawOrnatePool || !sawOrnateJewelleryBox)
		{
			achievements.unlock(Achievement.HOMEOWNERS_SHAME);
			announce("Brokie house.");
		}
	}

	/**
	 * Collects notable objects while a (possible) house is loading. Only runs in
	 * instanced regions, which is where player-owned houses live.
	 */
	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (!houseCheckPending || !client.isInInstancedRegion())
		{
			return;
		}

		ObjectComposition def = client.getObjectDefinition(event.getGameObject().getId());
		if (def != null && def.getImpostorIds() != null)
		{
			// Built furniture (pools, jewellery boxes...) are varbit-transformed
			// objects: the base definition is a nameless hotspot, the impostor is
			// what's actually built
			def = def.getImpostor();
		}
		String name = def == null ? null : def.getName();
		if (name == null || "null".equals(name))
		{
			return;
		}

		scannedObjectNames.add(name);

		if (POH_PORTAL_NAME.equalsIgnoreCase(name))
		{
			sawExitPortal = true;
		}
		else if (name.endsWith(POH_HOTSPOT_SUFFIX))
		{
			sawBuildHotspot = true;
		}
		else if (name.startsWith(POH_ORNATE_POOL_PREFIX))
		{
			sawOrnatePool = true;
		}
		else if (POH_ORNATE_JEWELLERY_BOX_NAME.equalsIgnoreCase(name))
		{
			sawOrnateJewelleryBox = true;
		}
	}

	/**
	 * Warns (once per session) when the bank is opened and its rough value —
	 * GE prices via ItemManager — is under the configured threshold.
	 */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.BANK.getId()
			|| !config.bankValueWarning() || bankWarnedThisSession)
		{
			return;
		}

		ItemContainer bank = event.getItemContainer();
		if (bank == null)
		{
			return;
		}

		long total = 0;
		for (Item item : bank.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				total += (long) itemManager.getItemPrice(item.getId()) * item.getQuantity();
			}
		}

		if (total < config.bankValueThreshold())
		{
			bankWarnedThisSession = true;
			achievements.unlock(Achievement.BROKIE_CERTIFIED);
			announce("Pfft. Bank value under " + String.format("%,d", config.bankValueThreshold())
				+ ". Brokie.");
		}
	}

	private void announce(String message)
	{
		if (config.chatMessagesEnabled() && client.getGameState() == GameState.LOGGED_IN)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
		}
	}
}

package com.skedpojkar;

import com.skedpojkar.announce.AnnouncementTriggers;
import com.skedpojkar.multiplayer.PartyGameMessage;
import com.skedpojkar.multiplayer.PartyTicTacToe;
import com.skedpojkar.panel.SkedpojkarPanel;
import com.skedpojkar.sound.SoundEngine;
import com.google.inject.Provides;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Skedpojkar",
	description = "Side panel idle-minigames, toggleable fun sounds and chat messages during certain in-game events.",
	tags = {"sound", "announce", "minigame", "party", "clan", "fun"}
)
public class SkedpojkarPlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private WSClient wsClient;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private net.runelite.client.game.ItemManager itemManager;

	@Inject
	private net.runelite.api.Client client;

	@Inject
	private net.runelite.client.callback.ClientThread clientThread;

	@Inject
	private SkedpojkarConfig config;

	@Inject
	private com.skedpojkar.achievements.AchievementManager achievementManager;

	@Inject
	private AnnouncementTriggers announcementTriggers;

	@Inject
	private SoundEngine soundEngine;

	@Inject
	private PartyTicTacToe partyTicTacToe;

	private SkedpojkarPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		eventBus.register(announcementTriggers);
		eventBus.register(partyTicTacToe);
		wsClient.registerMessage(PartyGameMessage.class);
		executor.execute(soundEngine::init);

		panel = new SkedpojkarPanel(config, configManager, client, clientThread, itemManager, partyTicTacToe, achievementManager);
		navButton = NavigationButton.builder()
			.tooltip("Skedpojkar")
			.icon(ImageUtil.loadImageResource(SkedpojkarPlugin.class, "icon.png"))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		log.info("Skedpojkar started");
	}

	@Override
	protected void shutDown()
	{
		// navButton can be null if startUp failed partway through
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		wsClient.unregisterMessage(PartyGameMessage.class);
		eventBus.unregister(announcementTriggers);
		eventBus.unregister(partyTicTacToe);
		partyTicTacToe.setBoardListener(null);
		panel = null;
		navButton = null;

		log.info("Skedpojkar stopped");
	}

	/** Clicker progress is stored per character, so re-read it when the character changes. */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		SkedpojkarPanel currentPanel = panel;
		if (currentPanel != null)
		{
			SwingUtilities.invokeLater(currentPanel.getRuneClickerPanel()::refresh);
		}
	}

	@Provides
	SkedpojkarConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SkedpojkarConfig.class);
	}
}

